<?php
/** R24 owned native saved-history, byte-preservation and isolated restore probes. */
declare(strict_types=1);

/** No effect occurs from including this module; every mode rechecks the owned route. */
function r24_history_command(string$mode,array$state,string$output):bool {
    if(!in_array($mode,['history-saved','history-probe','history-unsupported-probe','history-absent-probe','history-variants','history-future-seed','history-future-check','history-reinstall','history-lifecycle','history-restore','history-no-current'],true)){return false;}
    r24_route();r24_require(PHP_SAPI==='cli'&&defined('WP_CLI')&&WP_CLI&&isset($state['history_order_id'])&&is_int($state['history_order_id'])&&in_array($state['history_order_id'],$state['orders'],true));
    $order_id=$state['history_order_id'];
    if('history-probe'===$mode||'history-saved'===$mode){$result=r24_hist_probe($state,$order_id);r24_json($output,$result);return true;}
    if('history-unsupported-probe'===$mode){r24_json($output,r24_hist_unsupported_probe($state,$order_id));return true;}
    if('history-absent-probe'===$mode){r24_json($output,r24_hist_absent_probe($state,$order_id));return true;}
    if('history-variants'===$mode){r24_json($output,r24_hist_variants($state,$order_id));return true;}
    if('history-future-seed'===$mode){r24_json($output,r24_hist_future($state,$order_id,false));return true;}
    if('history-future-check'===$mode){r24_json($output,r24_hist_future($state,$order_id,true));return true;}
    if('history-reinstall'===$mode){r24_json($output,r24_hist_reinstall($state,$order_id));return true;}
    if('history-lifecycle'===$mode){r24_hist_observed_command($mode,$output,static fn():array=>r24_hist_lifecycle($state,$order_id));return true;}
    if('history-restore'===$mode){r24_json($output,r24_hist_restore($state,$order_id));return true;}
    if('history-no-current'===$mode){r24_hist_observed_command($mode,$output,static fn():array=>r24_hist_without_sources($state,$order_id));return true;}
    return false;
}

/** Private failure-only witness. Labels never contain native values or exception text. */
function r24_hist_diagnostic_label(mixed$step):string {
    $allowed=['entry','baseline','shipment_create','shipment_cards','shipment_render','shipment_preservation','replacement','retire_return','retire_refund','retire_rows','retire_attempt','retire_preservation','delete_products','disable_runtime','fresh_saved','saved_preservation','absent_history','absent_remove','absent_probe','absent_restore','source_plan','source_baseline','source_rename','source_probe','source_preservation','source_restore','output'];
    return is_string($step)&&in_array($step,$allowed,true)?$step:'unobserved';
}
function r24_hist_diagnostic_step(string$step):void {
    if(isset($GLOBALS['r24_hist_diagnostic_context']))$GLOBALS['r24_hist_diagnostic_context']['step']=r24_hist_diagnostic_label($step);
}
function r24_hist_diagnostic_failure(Throwable$error):void {
    if(isset($GLOBALS['r24_hist_diagnostic_context'])&&!isset($GLOBALS['r24_hist_diagnostic_context']['failure']))$GLOBALS['r24_hist_diagnostic_context']['failure']=['error'=>$error,'step'=>$GLOBALS['r24_hist_diagnostic_context']['step']];
}
function r24_hist_observed_command(string$mode,string$output,callable$work):void {
    $prior=$GLOBALS['r24_hist_diagnostic_context']??null;$GLOBALS['r24_hist_diagnostic_context']=['step'=>'entry'];
    try{r24_require(in_array($mode,['history-lifecycle','history-no-current'],true));$result=$work();r24_hist_diagnostic_step('output');r24_json($output,$result);}
    catch(Throwable$error){
        $context=$GLOBALS['r24_hist_diagnostic_context']??[];$failure=$context['failure']??null;$step=r24_hist_diagnostic_label(is_array($failure)&&($failure['error']??null)===$error?($failure['step']??null):($context['step']??null));
        $class=match(true){$error instanceof InvalidArgumentException=>'invalid_argument',$error instanceof RuntimeException=>'runtime',$error instanceof TypeError=>'type_error',$error instanceof Error=>'error',$error instanceof Exception=>'exception',default=>'other'};
        try{r24_json($output,['r24_history_failure'=>['mode'=>match($mode){'history-lifecycle'=>'lifecycle','history-no-current'=>'no_current',default=>'unobserved'},'step'=>$step,'class'=>$class]]);}catch(Throwable){}
        throw$error;
    }finally{if(null===$prior)unset($GLOBALS['r24_hist_diagnostic_context']);else$GLOBALS['r24_hist_diagnostic_context']=$prior;}
}

